<?php /** @package Meridian_News */ ?>
<article <?php post_class( 'single-article' ); ?>><header class="single-article__header"><p class="breadcrumbs"><a href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php esc_html_e( 'Home', 'meridian-news' ); ?></a><span aria-hidden="true">/</span><a href="<?php echo esc_url( get_permalink( get_option( 'page_for_posts' ) ) ?: home_url( '/' ) ); ?>"><?php esc_html_e( 'News', 'meridian-news' ); ?></a></p><?php meridian_news_categories(); ?><h1><?php the_title(); ?></h1><?php if ( has_excerpt() ) { ?><div class="single-article__dek"><?php the_excerpt(); ?></div><?php } ?><?php get_template_part( 'template-parts/post-meta' ); ?></header><?php if ( has_post_thumbnail() ) { ?><figure class="single-article__featured"><?php the_post_thumbnail( 'meridian-news-hero' ); ?></figure><?php } ?><div class="share-row"><span><?php esc_html_e( 'Share:', 'meridian-news' ); ?></span><?php $share_url = rawurlencode( get_permalink() ); $share_title = rawurlencode( get_the_title() ); ?><a href="https://www.linkedin.com/sharing/share-offsite/?url=<?php echo esc_attr( $share_url ); ?>" target="_blank" rel="noopener noreferrer">LinkedIn</a><a href="https://twitter.com/intent/tweet?url=<?php echo esc_attr( $share_url ); ?>&text=<?php echo esc_attr( $share_title ); ?>" target="_blank" rel="noopener noreferrer">X</a><button class="copy-link" type="button" data-copy-url="<?php echo esc_url( get_permalink() ); ?>"><?php esc_html_e( 'Copy link', 'meridian-news' ); ?></button></div><div class="entry-content"><?php the_content(); wp_link_pages(); ?></div><?php the_tags( '<div class="post-tags"><span>' . esc_html__( 'Tagged:', 'meridian-news' ) . '</span> ', ', ', '</div>' ); ?><nav class="post-navigation" aria-label="<?php esc_attr_e( 'Post navigation', 'meridian-news' ); ?>"><?php the_post_navigation( array( 'prev_text' => '← %title', 'next_text' => '%title →' ) ); ?></nav></article>
